using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Text;
using System.Diagnostics;
namespace JingYue {
 public static class IntegrationTests {
  static void Assert(bool ok,string name,StringBuilder log){if(!ok)throw new Exception("FAIL: "+name);log.AppendLine("PASS: "+name);}
  static void ZipText(ZipArchive zip,string path,string body){using(var s=zip.CreateEntry(path).Open())using(var w=new StreamWriter(s,new UTF8Encoding(false)))w.Write(body);}
  public static string CreateEpub(string root){string path=Path.Combine(root,"测试书.epub");using(var z=ZipFile.Open(path,ZipArchiveMode.Create)){
   ZipText(z,"mimetype","application/epub+zip");ZipText(z,"META-INF/container.xml","<?xml version='1.0'?><container xmlns='urn:oasis:names:tc:opendocument:xmlns:container'><rootfiles><rootfile full-path='OPS/package.opf' media-type='application/oebps-package+xml'/></rootfiles></container>");
   ZipText(z,"OPS/package.opf","<package xmlns='http://www.idpf.org/2007/opf' version='3.0' unique-identifier='id'><metadata xmlns:dc='http://purl.org/dc/elements/1.1/'><dc:identifier id='id'>jingyue-fixture</dc:identifier><dc:title>风与书页</dc:title><dc:creator>静阅测试</dc:creator><dc:language>zh</dc:language><meta property='dcterms:modified'>2026-10-25T00:00:00Z</meta></metadata><manifest><item id='two' href='text/second.xhtml' media-type='application/xhtml+xml'/><item id='nav' href='nav.xhtml' media-type='application/xhtml+xml' properties='nav'/><item id='one' href='text/first.xhtml' media-type='application/xhtml+xml'/></manifest><spine><itemref idref='one'/><itemref idref='two'/></spine></package>");
   ZipText(z,"OPS/nav.xhtml","<html xmlns='http://www.w3.org/1999/xhtml'><body><nav><a href='text/first.xhtml'>起点</a><a href='text/second.xhtml'>远方</a></nav></body></html>");
   ZipText(z,"OPS/text/first.xhtml","<html xmlns='http://www.w3.org/1999/xhtml'><head><title>不要读这里</title><style>.body{color:red}</style></head><body><h1>第一章 起点</h1><p>风穿过书页，阅读从这里开始。</p><p>这是第一章的正文 &amp; 标点。</p><script>不要执行脚本</script></body></html>");
   var second=new StringBuilder("<html xmlns='http://www.w3.org/1999/xhtml'><body><h1>第二章 远方</h1>");for(int i=0;i<400;i++)second.Append("<p>沿着这一行文字慢慢往前，每一页都有新的风景。这是段落 "+i+"。</p>");second.Append("</body></html>");ZipText(z,"OPS/text/second.xhtml",second.ToString());
  }return path;}
  public static void Run(StringBuilder log){string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"JingYueLibraryTest-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   string epub=CreateEpub(root);var d=Document.Read(epub,"自动");Assert(d.Title=="风与书页"&&d.Author=="静阅测试","EPUB metadata",log);Assert(d.Blocks[0].Text=="第一章 起点"&&d.Chapters[1].Text=="远方"&&d.Chapters[1].Index==3&&d.Blocks.Count==404,"EPUB spine order, EPUB3 navigation and all paragraphs",log);Assert(!d.Blocks.Any(p=>p.Text.Contains("不要"))&&d.Blocks.Any(p=>p.Text.Contains("& 标点")),"HTML scripts/head ignored, entities decoded",log);
   string epub2=Path.Combine(root,"EPUB2.epub");File.Copy(epub,epub2);using(var z=ZipFile.Open(epub2,ZipArchiveMode.Update)){z.GetEntry("OPS/package.opf").Delete();ZipText(z,"OPS/package.opf","<package xmlns='http://www.idpf.org/2007/opf' version='2.0'><manifest><item id='ncx' href='toc.ncx' media-type='application/x-dtbncx+xml'/><item id='body' href='body.xhtml' media-type='application/xhtml+xml'/></manifest><spine toc='ncx'><itemref idref='body'/></spine></package>");ZipText(z,"OPS/toc.ncx","<ncx xmlns='http://www.daisy.org/z3986/2005/ncx/'><navMap><navPoint><navLabel><text>卷一</text></navLabel><content src='body.xhtml#first'/></navPoint><navPoint><navLabel><text>卷二</text></navLabel><content src='body.xhtml#second'/></navPoint></navMap></ncx>");ZipText(z,"OPS/body.xhtml","<html><body><p id='first'>第一段</p><p>正文</p><p id='second'>第三段</p><p>结尾</p></body></html>");}d=Document.Read(epub2,"自动");Assert(d.Chapters.Count==2&&d.Chapters[1].Text=="卷二"&&d.Chapters[1].Index==2,"EPUB2 NCX / fragment targets without heading tags",log);
   string html=Path.Combine(root,"test.html");File.WriteAllText(html,"<!doctype html><html><head><title>ignore</title></head><body><h2>标题</h2><p>段落一<br>段落二</p><ul><li>清单</li></ul></body></html>");d=Document.Read(html,"自动");Assert(d.Chapters.Count==1&&d.Blocks.Any(p=>p.Text=="段落二"),"HTML import / headings / line breaks",log);
   string fb2=Path.Combine(root,"test.fb2");File.WriteAllText(fb2,"<?xml version='1.0' encoding='utf-8'?><FictionBook xmlns='http://www.gribuser.ru/xml/fictionbook/2.0'><description><title-info><book-title>故事</book-title></title-info></description><body><section><title><p>第一章</p></title><p>正文<emphasis>强调</emphasis></p></section></body><binary>IGNORE</binary></FictionBook>");d=Document.Read(fb2,"自动");Assert(d.Title=="故事"&&d.Blocks.Count==2&&d.Chapters.Count==1&&!d.Blocks.Any(p=>p.Text.Contains("IGNORE")),"FB2 metadata / body / chapters",log);
   string docx=Path.Combine(root,"test.docx");using(var z=ZipFile.Open(docx,ZipArchiveMode.Create))ZipText(z,"word/document.xml","<w:document xmlns:w='http://schemas.openxmlformats.org/wordprocessingml/2006/main'><w:body><w:p><w:pPr><w:pStyle w:val='Heading1'/></w:pPr><w:r><w:t>第一章 标题</w:t></w:r></w:p><w:p><w:r><w:t>正文</w:t></w:r></w:p></w:body></w:document>");d=Document.Read(docx,"自动");Assert(d.Blocks.Count==2&&d.Chapters.Count==1,"DOCX paragraph and heading import",log);
   var store=new LibraryStore(Path.Combine(root,"library"));var cfg=store.Load();var prepared=store.Prepare(epub,"自动");var b=store.Register(cfg,prepared);b.Position=101;b.ParagraphOffset=.37;b.LastChapter="第二章 远方";b.Marks.Add(101);store.Save(cfg);string duplicate=Path.Combine(root,"copy.epub");File.Copy(epub,duplicate);var same=store.Register(cfg,store.Prepare(duplicate,"自动"));Assert(cfg.Books.Count==1&&Object.ReferenceEquals(b,same)&&same.Position==101,"Content deduplication preserves progress",log);store.Save(cfg);File.Delete(epub);File.Delete(duplicate);var saved=store.Load().Books[0];Assert(File.Exists(saved.Path)&&Document.Read(saved.Path,"自动").Blocks.Count==404,"Persistent library works after source removal",log);Assert(saved.Position==101&&Math.Abs(saved.ParagraphOffset-.37)<.001&&saved.Marks.Contains(101)&&saved.LastChapter=="第二章 远方","Reading location / offset / chapter / bookmarks survive restart",log);
   for(int i=0;i<40;i++)cfg.Books.Add(new Book{Path="fixture"+i,Title="book"+i});store.Save(cfg);Assert(store.Load().Books.Count==41,"Library has no 30-book history eviction",log);
   File.WriteAllText(Path.Combine(store.Root,"settings.xml"),"broken");Assert(store.Load().Books.Count==1,"Atomic index backup recovery",log);
  }finally{Directory.Delete(root,true);}}
  public static void Samples(string folder,StringBuilder log){foreach(string path in Directory.GetFiles(folder).Where(p=>Formats.Extensions.Contains(Path.GetExtension(p).ToLowerInvariant()))){var sw=Stopwatch.StartNew();var doc=Document.Read(path,"自动");if(doc.Blocks.Count<100||doc.Chapters.Count<1)throw new Exception("Sample lacks expected text or chapters: "+path);log.AppendLine(String.Format("SAMPLE: {0} | {1:N0} bytes | {2:N0} chars | {3:N0} paragraphs | {4:N0} chapters | {5:N0} ms",Path.GetFileName(path),new FileInfo(path).Length,doc.Characters,doc.Blocks.Count,doc.Chapters.Count,sw.ElapsedMilliseconds));}}
  public static void PreparePreview(string root,string samples){var store=new LibraryStore(root);var settings=store.Load();foreach(string path in Directory.GetFiles(samples).Where(p=>Formats.Extensions.Contains(Path.GetExtension(p).ToLowerInvariant()))){var prepared=store.Prepare(path,"自动");store.Register(settings,prepared);}string epub=Path.Combine(Path.GetDirectoryName(root),"测试书.epub");if(!File.Exists(epub))CreateEpub(Path.GetDirectoryName(root));var book=store.Register(settings,store.Prepare(epub,"自动"));book.Position=120;book.ParagraphOffset=.25;book.LastChapter="第二章 远方";book.LastReadUtc=DateTime.UtcNow.ToString("o");store.Save(settings);}
 }
}
